#[tokio::test]
async fn test_revolutionary_multiple_type_safe_migrations() {
    let db = D1Client::new_in_memory().await.expect("Failed to create database");
    
    let mut runner = MigrationRunner::new();
    
    // 🚀 REVOLUTIONARY: Multiple type-safe migrations - impossible to have typos!
    let users_migration = TestUser::create_table_migration("create_users", 1);
    let posts_migration = Post::create_table_migration("create_posts", 2);
    let comments_migration = Comment::create_table_migration("create_comments", 3);
    
    runner.add_migration(Box::new(users_migration));
    runner.add_migration(Box::new(posts_migration));
    runner.add_migration(Box::new(comments_migration));
    
    // Run migrations
    runner.run_pending_migrations(&db)
        .await
        .expect("Failed to run migrations");
    
    // Verify all tables were created with correct schema
    let tables = db.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name IN ('test_users', 'posts', 'comments') ORDER BY name",
        &[]
    ).await.expect("Failed to query tables");
    
    assert_eq!(tables.rows.len(), 3);
    
    // Verify all migrations were recorded
    let migrations = db.execute(
        "SELECT name, version FROM _migrations ORDER BY version",
        &[]
    ).await.expect("Failed to query migrations");
    
    assert_eq!(migrations.rows.len(), 3);
}

#[tokio::test]
async fn test_revolutionary_migration_idempotency() {
    let db = D1Client::new_in_memory().await.expect("Failed to create database");
    
    let mut runner = MigrationRunner::new();
    
    // 🚀 REVOLUTIONARY: Type-safe idempotent migration
    let migration = TestUser::create_table_migration("idempotent_test", 1);
    
    runner.add_migration(Box::new(migration));
    
    // Run migrations first time
    runner.run_pending_migrations(&db)
        .await
        .expect("Failed to run migrations first time");
    
    // Run migrations second time - should not fail
    runner.run_pending_migrations(&db)
        .await
        .expect("Failed to run migrations second time");
    
    // Verify migration was only recorded once
    let migrations = db.execute(
        "SELECT * FROM _migrations WHERE name='idempotent_test'",
        &[]
    ).await.expect("Failed to query migrations");
    
    assert_eq!(migrations.rows.len(), 1);
}

